package org.freecad.mobilelab;
import org.json.*;import java.util.*;
public final class MobileWorkflowRegression {
 static int checks;interface Action{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void near(double a,double b){check(Math.abs(a-b)<1e-7,"Expected "+b+", got "+a);}static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid workflow accepted");}
 public static void main(String[] args)throws Exception{NativeCad.clear();ProjectStore.reset();for(int count:new int[]{2,3,4,6,10}){ArrayList<double[]> poles=new ArrayList<>();double[] flat=new double[count*4];for(int i=0;i<count;i++){double[] p={i*2-10,5*Math.sin(i),i/3.,.25+(i%4)*.7};poles.add(p);System.arraycopy(p,0,flat,i*4,4);}int id=NativeCad.curve("NURBS curve",flat,false,0);for(int i=0;i<=32;i++){double t=i/32.;double[] expected=NativeCad.samplePoint(id,new double[]{t}),actual=SketchMath.nurbs(poles,t);for(int j=0;j<3;j++)near(actual[j],expected[j]);}NativeCad.remove(id);}ArrayList<double[]> points=new ArrayList<>();points.add(new double[]{0,0,0,1});points.add(new double[]{10,10,0,1});points.add(new double[]{0,10,0,1});points.add(new double[]{10,0,0,1});SketchMath.Snap p=SketchMath.snap(.1,.1,1,.5,points,-1,true,false);check(p.kind.equals("point"),"Endpoint snap");near(p.x,0);p=SketchMath.snap(5.1,5.1,1,.5,points,-1,true,false);check(p.kind.equals("midpoint"),"Midpoint tie priority");points.set(1,new double[]{8,8,0,1});points.set(2,new double[]{0,8,0,1});p=SketchMath.snap(4.5,4.5,1,.5,points,-1,true,false);check(p.kind.equals("intersection"),"Segment intersection snap");near(p.x,40./9);near(p.y,40./9);p=SketchMath.snap(15.1,.2,1,.1,points,-1,false,true);check(p.kind.equals("horizontal assist"),"Ortho assistance");near(p.y,0);reject(()->SketchMath.snap(0,0,0,.5,points,-1,true,false));
  int box=NativeCad.create("Box",new double[]{10,8,6}),curve=NativeCad.create("Circle",new double[]{8}),surface=NativeCad.create("NURBS patch",new double[]{30,30,0});double[] centre={0,0,100,0,0,-1,.2};check(NativeCad.pickFiltered(centre,"Solids")==box,"Solid selection filter");check(NativeCad.pickFiltered(centre,"Surfaces")==surface,"Surface selection filter");check(NativeCad.pickFiltered(new double[]{8,0,100,0,0,-1,.3},"Curves")==curve,"Curve selection filter");check(NativeCad.pickFiltered(centre,"Meshes")==0,"Mesh filter selected CAD");NativeCad.visible(curve,false);NativeCad.visible(surface,false);int[] face=NativeCad.pickElement(centre,1);check(face[0]==box&&face[1]==1&&face[2]>0,"Face ray selection");int[] edge=NativeCad.pickElement(new double[]{0,-4,100,0,0,-1,.3},2);check(edge[0]==box&&edge[2]>0,"Exact edge selection");int[] vertex=NativeCad.pickElement(new double[]{-5,-4,100,0,0,-1,.3},3);check(vertex[0]==box&&vertex[2]>0,"Topological vertex selection");NativeCad.properties(box,"Locked","Default",true);check(NativeCad.pickElement(centre,1)[0]==0,"Locked face selectable");NativeCad.properties(box,"Unlocked","Default",false);
  int root=NativeCad.create("Rectangle",new double[]{10,6});int pad=FeatureModel.model("Extrude solid",new int[]{root},new double[]{0,0,2});reject(()->FeatureModel.independent(new int[]{root,pad}));FeatureModel.independent(new int[]{root,box});NativeCad.beginTransaction(true);try{FeatureModel.removeMany(new int[]{root,pad});NativeCad.commitTransaction();}catch(Throwable x){NativeCad.rollbackTransaction();throw x;}check(FeatureModel.recipe(pad)==null,"Batch delete retained recipe");JSONArray data=new JSONArray(NativeCad.objects());for(int i=0;i<data.length();i++)check(data.getJSONObject(i).getInt("id")!=root&&data.getJSONObject(i).getInt("id")!=pad,"Dependency batch deletion failed");
  System.out.println("PASS: "+checks+" mobile workflow assertions: rational XY preview matches native NURBS, point/midpoint/intersection/ortho assists, object filters, exact face/edge/vertex picking, lock enforcement and dependency-aware batch deletion");
 }
}
